          'function load(key, initial) {',
          '  try { return key in storage ? JSON.parse(storage[key]) : initial; }',
          '  catch { return initial; }',
          '}',
          'function save(key, value) { storage[key] = JSON.stringify(value); }',
          '',
          'let jobs = load("jobs", []);',
          'jobs = [...jobs, { id: 1 }];',
          'save("jobs", jobs);',
          'console.log(load("jobs", []));',
